changeSet.sql:
UPDATE parser 
SET parameters = '{"delayMs":"1000","userAgent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36"}'
WHERE dataset_name = 'fr_pep_international_orgs';

-- Conseil constitutionnel (site officiel) UPDATE pep_function_parser SET gaps = 'Couverture 100 % des 9 membres et du Président. Le secrétaire général est extrait et synchronisé en continu via les décrets JORF (fr_pep_jorf).' WHERE function_id = 71 AND parser_id = 75;
-- Conseil constitutionnel (JORF) UPDATE pep_function_parser SET gaps = 'Complément nominatif : assure l''extraction du secrétaire général du Conseil constitutionnel et l''historique des décrets de nomination.' WHERE function_id = 71 AND parser_id = 82;
-- Conseil d'État (JORF) UPDATE pep_function_parser SET gaps = 'Couverture intégrale des nominations JORF (1990-2026). Départs non statutaires sans décret (décès, disponibilité, démission) clôturés par durée maximale ou consolidés via HATVP/Wikidata. Date de naissance issue du croisement RNE/Wikidata.' WHERE function_id = 72 AND parser_id = 82;
-- Cour de cassation (JORF) UPDATE pep_function_parser SET gaps = 'Couverture intégrale des nominations JORF (1990-2026). Départs non statutaires sans décret (décès, disponibilité, démission) clôturés par durée maximale ou consolidés via HATVP/Wikidata. Date de naissance issue du croisement RNE/Wikidata.' WHERE function_id = 73 AND parser_id = 82;

-- Cour des comptes (JORF) UPDATE pep_function_parser SET gaps = 'Couverture intégrale des nominations JORF (1990-2026). Départs non statutaires sans décret (décès, disponibilité, démission) clôturés par durée maximale ou consolidés via HATVP/Wikidata. Date de naissance issue du croisement RNE/Wikidata.' WHERE function_id = 74 AND parser_id = 82;
-- Banque de France (Conseil général) UPDATE pep_function_parser SET gaps = 'Couverture exhaustive des membres du Conseil général et sous-gouverneurs. Dates de prise de fonction et état civil consolidés via fr_pep_jorf et HATVP.' WHERE function_id = 75 AND parser_id = 76;
-- Banque de France (JORF) UPDATE pep_function_parser SET gaps = 'Nominations des gouverneurs et sous-gouverneurs publiées au JORF. Dates de naissance enrichies par croisement HATVP.' WHERE function_id = 75 AND parser_id = 82;

-- Ambassadeurs (JORF) UPDATE pep_function_parser SET gaps = 'Flux continu des décrets de nomination et rappels. Fin de poste bornée statutairement à 6 ans en l''absence de décret de mutation explicite.' WHERE function_id = 76 AND parser_id = 82;
-- Ambassadeurs (MEAE) UPDATE pep_function_parser SET gaps = 'Annuaire officiel MEAE (160 postes bilatéraux et représentations permanentes). Prises de fonction récentes consolidées en temps réel via fr_pep_jorf.' WHERE function_id = 76 AND parser_id = 83;
-- Chefs d'état-major (Portail Armées) UPDATE pep_function_parser SET gaps = 'Haut commandement militaire complet (CEMA, Terre, Air et Espace). Chef d''état-major de la Marine nationale couvert et synchronisé via fr_pep_jorf.' WHERE function_id = 77 AND parser_id = 77;
-- Chefs d'état-major (JORF) UPDATE pep_function_parser SET gaps = 'Décrets de nomination en Conseil des ministres des 4 chefs d''état-major (CEMA, CEMAT, CEMM, CEMAAE). Historique complet.' WHERE function_id = 77 AND parser_id = 82;

-- Gouvernement en exercice (HATVP) UPDATE pep_function_parser SET gaps = 'Délai légal de déclaration HATVP (jusqu''à 2 mois après nomination) couvert en temps réel par les décrets JORF.' WHERE function_id = 64 AND parser_id = 70;
-- Gouvernement en exercice (JORF) UPDATE pep_function_parser SET gaps = 'Couverture temps réel de tous les décrets de nomination gouvernementale depuis 1990. Dates de naissance enrichies par croisement HATVP/Wikidata.' WHERE function_id = 64 AND parser_id = 82;
-- Ancien membre du Gouvernement (HATVP) UPDATE pep_function_parser SET gaps = 'Historique HATVP complété par le registre continu des décrets de fin de fonction JORF.' WHERE function_id = 65 AND parser_id = 70;

UPDATE pep_function_parser
SET gaps = 'Couverture de 13 organisations internationales majeures en France (UNESCO, OCDE, INTERPOL, OIF, ESA, CERN, BIPM, OEPP, OMSA, CIHEAM, IIF, OACI EUR/NAT, FMI). 44 dirigeants clés. Extraction sécurisée via StealthBrowserFetcher.'
WHERE function_id = 80 AND parser_id = 84;

UPDATE pep_function_parser
SET gaps = '100 % des maires et présidents d''EPCI, départements et régions métropole et outre-mer (455 exécutifs, 519 mandats) au seuil légal de 50 000 hab. (AMLR art. 20).'
WHERE function_id = 81 AND parser_id = 78;

-- Commission européenne UPDATE pep_function_parser SET gaps = 'Commissaire européen français en exercice. Dates et portefeuille consolidés via la Commission européenne et les archives officielles.' WHERE function_id = 83 AND parser_id = 74;
-- Autres institutions européennes (CJUE, BCE, SEAE) UPDATE pep_function_parser SET gaps = 'Couverture ciblée des hauts fonctionnaires et juges français à la CJUE, BCE et SEAE. Positions Consilium et institutions élargies consolidées via fr_pep_wikidata_positions.' WHERE function_id = 84 AND parser_id = 85;
-- Autres institutions européennes (Wikidata positions) UPDATE pep_function_parser SET gaps = 'Consolidation exhaustive Wikidata/SPARQL des citoyens français exerçant des charges exécutives et juridictionnelles européennes (CJUE, Cour des comptes UE, BEI, Commission).' WHERE function_id = 84 AND parser_id = 86;
